/* shaders.js — GLSL for the UO-style pixel pipeline.
 *
 * Two passes into a low-res render target (object shader, uPass 0 = colour, 1 = world normals),
 * then one full-screen post pass (outlines, night tint) that upscales to the canvas with
 * nearest-neighbour sampling.
 */
var SHADERS = (function () {
  var common = [
    '// 4x4 ordered (Bayer) dither, returns 0..15/16 for integer pixel coords',
    'float bayer2(vec2 a){ a = floor(a); return fract(a.x / 2.0 + a.y * a.y * 0.75); }',
    'float bayer4(vec2 a){ return bayer2(0.5 * a) * 0.25 + bayer2(a); }',
    'float hash12(vec2 p){ vec3 p3 = fract(vec3(p.xyx) * 0.1031); p3 += dot(p3, p3.yzx + 33.33); return fract((p3.x + p3.y) * p3.z); }',
    'float vnoise(vec2 p){',
    '  vec2 i = floor(p); vec2 f = fract(p); f = f * f * (3.0 - 2.0 * f);',
    '  float a = hash12(i), b = hash12(i + vec2(1.0, 0.0)), c = hash12(i + vec2(0.0, 1.0)), d = hash12(i + vec2(1.0, 1.0));',
    '  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);',
    '}',
  ].join('\n');

  // ---------------------------------------------------------------- object pass
  var objVert = [
    'uniform vec2 uRes;',
    'uniform float uSnap;',
    'uniform vec3 uSnapOrigin;',
    'varying vec3 vWorldPos;',
    'varying vec3 vWorldNormal;',
    'varying float vViewZ;',
    'varying float vMat;',
    '#ifdef TERRAIN',
    '  attribute float aLoose;',
    '  attribute float aFaced;',
    '  varying float vLoose;',
    '  varying float vFaced;',
    '#else',
    '  attribute float aMat;',
    '#endif',
    'void main(){',
    '  vec4 wp = modelMatrix * vec4(position, 1.0);',
    '  vWorldPos = wp.xyz;',
    '  vWorldNormal = normalize(mat3(modelMatrix) * normal);',
    '  vec4 vp = viewMatrix * wp;',
    '  vViewZ = vp.z;',
    '  vec4 clip = projectionMatrix * vp;',
    '#ifdef TERRAIN',
    '  vLoose = aLoose;',
    '  vFaced = aFaced;',
    '  vMat = 0.0;',
    '#else',
    '  vMat = aMat;',
    '  // Snap the whole object so its origin lands on a pixel centre: sprite-like stability.',
    '  if (uSnap > 0.5) {',
    '    vec4 oc = projectionMatrix * viewMatrix * vec4(uSnapOrigin, 1.0);',
    '    vec2 opix = (oc.xy / oc.w * 0.5 + 0.5) * uRes;',
    '    vec2 spix = floor(opix) + 0.5;',
    '    clip.xy += (spix - opix) / uRes * 2.0 * clip.w;',
    '  }',
    '#endif',
    '  gl_Position = clip;',
    '}',
  ].join('\n');

  var objFrag = [
    'uniform sampler2D uPalette;',
    'uniform float uPass;',
    'uniform vec3 uSunDir;',
    'uniform float uAmbient;',
    'uniform float uRamps;',
    'uniform float uDither;',
    'uniform float uSurfNoise;',
    'uniform float uNightMul;',
    'uniform float uSteps;',
    'uniform float uNumMats;',
    'uniform float uTime;',
    'uniform float uCutout;',
    'uniform float uCutEnabled;',
    'uniform vec2 uPlayerPix;',
    'uniform float uPlayerViewZ;',
    'uniform float uCutRadius;',
    'uniform float uCutMargin;',
    'uniform vec3 uBrush;',
    'uniform float uGhost;    // 1 = draw as a screen-door ghost (eliminated player)',
    'uniform float uFlash;    // 1 = just took damage: the whole body goes bone white for a few frames',
    'uniform vec4 uTown;      // x, z, strength, facing angle',
    'uniform vec3 uTownShape; // width, reach ahead, reach behind',
    'uniform float uThr;',
    'uniform vec3 uArena;     // x, z, radius: the paved ring at the rim and the sand floor inside it',
    'varying vec3 vWorldPos;',
    'varying vec3 vWorldNormal;',
    'varying float vViewZ;',
    'varying float vMat;',
    '#ifdef TERRAIN',
    '  varying float vLoose;',
    '  varying float vFaced;',
    '#endif',
    common,
    '// Town ward field: a lobe, short behind the town and long in its facing direction.',
    'float ward(vec2 p){',
    '  vec2 d = p - uTown.xy;',
    '  vec2 f = vec2(cos(uTown.w), sin(uTown.w));',
    '  float along = dot(d, f);',
    '  float perp = d.x * f.y - d.y * f.x;',
    '  float L = along >= 0.0 ? uTownShape.y : uTownShape.z;',
    '  return uTown.z * exp(-(perp * perp / (uTownShape.x * uTownShape.x) + along * along / (L * L)));',
    '}',
    'vec3 ramp(float matId, float s){',
    '  return texture2D(uPalette, vec2((s + 0.5) / uSteps, (matId + 0.5) / uNumMats)).rgb;',
    '}',
    'void main(){',
    '#ifdef SHADOW',
    '  // Blob shadow: a 50% screen-door disc in the darkest ramp colour; skipped in the normal pass so it draws no edges.',
    '  if (uPass > 0.5 || bayer4(gl_FragCoord.xy) < 0.5) discard;',
    '  gl_FragColor = vec4(ramp(13.0, 0.0), 1.0); return;',
    '#endif',
    '  if (uGhost > 0.5 && bayer4(gl_FragCoord.xy) < 0.5) discard; // half the pixels: a ghost',
    '  vec3 n = normalize(vWorldNormal);',
    '  // Occluder cut-away: anything nearer the camera than the player inside a screen-space disc is',
    '  // dropped, with a dithered rim so the hole reads as a stippled sprite edge.',
    '  if (uCutout > 0.5 && uCutEnabled > 0.5) {',
    '    float d = distance(gl_FragCoord.xy, uPlayerPix);',
    '    if (d < uCutRadius && vViewZ > uPlayerViewZ + uCutMargin) {',
    '      float rim = smoothstep(uCutRadius - 6.0, uCutRadius, d);',
    '      if (bayer4(gl_FragCoord.xy) >= rim) discard;',
    '    }',
    '  }',
    '  if (uPass > 0.5) { gl_FragColor = vec4(n * 0.5 + 0.5, 1.0); return; }',
    '',
    '  float matId = vMat;',
    '  float speckle = 1.0;',
    '#ifdef TERRAIN',
    '  // Material is decided per fragment from height and slope, so sculpted terrain never needs',
    '  // transition tiles. The half-tile jitter makes boundaries chunky instead of smooth curves.',
    '  float h = vWorldPos.y;',
    '  float slope = 1.0 - n.y;',
    '  float j = hash12(floor(vWorldPos.xz * 2.0)) - 0.5;',
    '  matId = 0.0;',
    '  if (h < 0.25 + j * 0.3) matId = 3.0;',
    '  if (slope > 0.28 + j * 0.12) matId = 1.0;',
    '  if (slope > 0.55 + j * 0.1) matId = 2.0;',
    '  if (h > 3.4 + j * 0.6 && slope > 0.1) matId = 2.0;',
    '  if (h > 4.6 + j * 0.5) matId = 14.0;',
    '  if (vLoose > 0.3 + j * 0.2 && matId == 0.0) matId = 1.0; // disturbed earth shows as dirt',
    '  if (vFaced > 0.5) matId = 2.0;                              // stone facing',
    '  // The arena is unmissable underfoot: grass, then a cobbled ring a tile and a half wide at the',
    '  // rim, then the sand floor. Chunky edges from the same jitter as everything else.',
    '  float ad = distance(vWorldPos.xz, uArena.xy);',
    '  if (ad < uArena.z + 0.3 + j * 0.3) matId = 16.0;',
    '  if (ad < uArena.z - 1.4 + j * 0.4) matId = 3.0;',
    '  float wf = ward(vWorldPos.xz);',
    '  float wl = abs(wf - uThr) / max(fwidth(wf), 1e-6); // distance to the ward threshold, in pixels',
    '  if (wl < 1.5 && bayer4(gl_FragCoord.xy) < 0.75) matId = 16.0; // dotted stone line',
    '#else',
    '  speckle = 0.5;',
    '#endif',
    '',
    '  float ndl = max(dot(n, uSunDir), 0.0);',
    '  float inten = uAmbient + (1.0 - uAmbient) * ndl;',
    '  inten *= uNightMul;',
    '  // Cheap "texture": a per-cell speckle nudges the ramp index around.',
    '  vec2 cell = floor(vWorldPos.xz * 6.0) + floor(vWorldPos.y * 6.0) * vec2(7.0, 3.0);',
    '  inten += (hash12(cell) - 0.5) * uSurfNoise * speckle * (1.2 / uSteps);',
    '  if (matId == 4.0) {',
    '    float w = vnoise(vWorldPos.xz * 0.6 + vec2(uTime * 0.25, uTime * 0.17))',
    '            + 0.5 * vnoise(vWorldPos.xz * 1.3 - vec2(uTime * 0.2, uTime * 0.1));',
    '    inten += (w / 1.5 - 0.5) * 0.5;',
    '  }',
    '',
    '  vec3 col;',
    '  if (uRamps > 0.5) {',
    '    float dth = (bayer4(gl_FragCoord.xy) - 0.5) * uDither / uSteps;',
    '    float s = floor(clamp(inten + dth, 0.0, 0.999) * uSteps);',
    '    col = ramp(matId, s);',
    '  } else {',
    '    vec3 base = ramp(matId, uSteps - 3.0);',
    '    col = base * (0.3 + 0.9 * inten);',
    '  }',
    '  col = mix(col, vec3(1.0, 0.96, 0.88), uFlash);',
    '#ifdef TERRAIN',
    '  if (uBrush.z > 0.0) {',
    '    float dd = distance(vWorldPos.xz, uBrush.xy);',
    '    if (abs(dd - uBrush.z) < 0.1) col = mix(col, vec3(1.0, 0.85, 0.3), 0.85);',
    '  }',
    '#endif',
    '  gl_FragColor = vec4(col, 1.0);',
    '}',
  ].join('\n');

  // ---------------------------------------------------------------- post pass
  var postVert = [
    'varying vec2 vUv;',
    'void main(){ vUv = uv; gl_Position = vec4(position.xy, 0.0, 1.0); }',
  ].join('\n');

  var postFrag = [
    'uniform sampler2D tColor;',
    'uniform sampler2D tNormal;',
    'uniform sampler2D tDepth;',
    'uniform vec2 uRes;',
    'uniform float uOutline;',
    'uniform float uCreases;',
    'uniform float uDepthThr;',
    'uniform float uNormThr;',
    'uniform float uNight;',
    'varying vec2 vUv;',
    'void main(){',
    '  vec2 px = 1.0 / uRes;',
    '  vec3 col = texture2D(tColor, vUv).rgb;',
    '  if (uOutline > 0.5) {',
    '    // Depth silhouette: darken a pixel whose neighbour is farther away (line sits on the object).',
    '    float d  = texture2D(tDepth, vUv).r;',
    '    float dR = texture2D(tDepth, vUv + vec2(px.x, 0.0)).r;',
    '    float dL = texture2D(tDepth, vUv - vec2(px.x, 0.0)).r;',
    '    float dU = texture2D(tDepth, vUv + vec2(0.0, px.y)).r;',
    '    float dD = texture2D(tDepth, vUv - vec2(0.0, px.y)).r;',
    '    float farther = max(max(dR - d, dL - d), max(dU - d, dD - d));',
    '    float edge = step(uDepthThr, farther);',
    '    if (uCreases > 0.5) {',
    '      // Crease: forward difference only, so the line is one pixel wide.',
    '      vec3 n  = texture2D(tNormal, vUv).rgb * 2.0 - 1.0;',
    '      vec3 nR = texture2D(tNormal, vUv + vec2(px.x, 0.0)).rgb * 2.0 - 1.0;',
    '      vec3 nD = texture2D(tNormal, vUv - vec2(0.0, px.y)).rgb * 2.0 - 1.0;',
    '      float nd = max(1.0 - dot(n, nR), 1.0 - dot(n, nD));',
    '      edge = max(edge, step(uNormThr, nd));',
    '    }',
    '    col = mix(col, col * 0.35, edge);',
    '  }',
    '  col = mix(col, col * vec3(0.5, 0.6, 1.0), uNight * 0.7);',
    '  gl_FragColor = vec4(col, 1.0);',
    '}',
  ].join('\n');

  return { objVert: objVert, objFrag: objFrag, postVert: postVert, postFrag: postFrag };
})();
